            eprintln!("the '{}' option doesn't have an associated value", f);
            return ExitCode::from(1);
        }
        Err(args::ParseErr::ParseFail(msg)) => {
            eprintln!("{}", msg);
            return ExitCode::from(1);
        }
        Err(args::ParseErr::Runtime(msg)) => {
            eprintln!("tuc: runtime error. {}", msg);
            return ExitCode::from(1);
        }
    };

    // Read input
    let mut input: Vec<u8> = Vec::new();
    if let Some(path) = &args.filepath {
        let f = match File::open(path) {
            Ok(f) => f,
            Err(_) => {
                eprintln!("tuc: runtime error. The file \"{}\" does not exist", path);
                return ExitCode::from(1);
            }
        };
        let mut br = BufReader::new(f);
        if let Err(e) = br.read_to_end(&mut input) {
            eprintln!("tuc: runtime error. {}", e);
            return ExitCode::from(1);
        }
    } else {
        let stdin = io::stdin();
        let mut lock = stdin.lock();
        if let Err(e) = lock.read_to_end(&mut input) {
            eprintln!("tuc: runtime error. {}", e);
            return ExitCode::from(1);
        }
    }

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    let stderr = io::stderr();
    let mut err_out = BufWriter::new(stderr.lock());

    let code = match cut::run(&args, &input, &mut out, &mut err_out) {
        Ok(()) => ExitCode::SUCCESS,
        Err(cut::RunErr::OutOfBounds(msg)) => {
            // flush stdout first
            let _ = out.flush();
            let _ = writeln!(err_out, "Error: Out of bounds: {}", msg);
            ExitCode::from(1)
        }
        Err(cut::RunErr::Runtime(msg)) => {
            let _ = out.flush();
            let _ = writeln!(err_out, "tuc: runtime error. {}", msg);
            ExitCode::from(1)
        }
    };

    let _ = out.flush();
    let _ = err_out.flush();
    code
}

