// CLI argument parsing

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Mode {
    Fields,
    Bytes,
    Characters,
    Lines,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Trim {
    Left,
    Right,
    Both,
}

#[derive(Debug, Clone)]
pub struct Args {
    pub mode: Mode,
    pub bounds: String,
    pub delimiter: String,
    pub regex: Option<String>,
    pub greedy: bool,
    pub compress: bool,
    pub only_delimited: bool,
    pub zero_terminated: bool,
    pub complement: bool,
    pub join: Option<bool>, // None=default, Some(true)=join, Some(false)=no-join
    pub json: bool,
    pub no_mmap: bool,
    pub replace_delimiter: Option<String>,
    pub trim: Option<Trim>,
    pub fallback_oob: Option<String>,
    pub fixed_memory: Option<u64>,
    pub filepath: Option<String>,
    pub bounds_was_set: bool,
}

impl Args {
    fn default_state() -> Self {
        Args {
            mode: Mode::Fields,
            bounds: "1:".to_string(),
            delimiter: "\t".to_string(),
            regex: None,
            greedy: false,
            compress: false,
            only_delimited: false,
            zero_terminated: false,
            complement: false,
            join: None,
            json: false,
            no_mmap: false,
            replace_delimiter: None,
            trim: None,
            fallback_oob: None,
            fixed_memory: None,
            filepath: None,
            bounds_was_set: false,
        }
    }
}

pub enum ParseErr {
    PrintHelpIntro,
    PrintHelp,
    PrintVersion,
    Unexpected(String),
    MissingValue(String),
    ParseFail(String),
    Runtime(String),
}

// Check if an argument starts with value for short option (e.g. -d,)
// returns (flag_matched, value)
fn short_with_val<'a>(arg: &'a str, flag: char) -> Option<&'a str> {
    let bytes = arg.as_bytes();
    if bytes.len() >= 2 && bytes[0] == b'-' && bytes[1] as char == flag && bytes.len() > 2 {
        let rest = &arg[2..];
        // if rest starts with '=', the '=' is separator
        if let Some(stripped) = rest.strip_prefix('=') {
            Some(stripped)
        } else {
            Some(rest)
        }
    } else {
        None
    }
}

fn long_with_val<'a>(arg: &'a str, flag: &str) -> Option<&'a str> {
    let prefix = format!("--{}=", flag);
    if let Some(v) = arg.strip_prefix(&prefix) {
        Some(v)
    } else {
        None
    }
}

pub fn parse_args(raw: &[String]) -> Result<Args, ParseErr> {
    let mut args = Args::default_state();
    let mut has_any = false;
    let mut i = 0usize;
    let mut positional: Vec<String> = Vec::new();
    let mut unexpected: Vec<String> = Vec::new();

    // Early: handle -h/--help and -V/--version
    for a in raw {
        if a == "-h" || a == "--help" {
            return Err(ParseErr::PrintHelp);
        }
        if a == "-V" || a == "--version" {
            return Err(ParseErr::PrintVersion);
        }
    }

    while i < raw.len() {
        let a = &raw[i];
        let abs = a.as_str();

        if abs == "--" {
            // remaining are positional
            for p in &raw[i+1..] {
                positional.push(p.clone());
            }
            break;
        }

        // Long options
        if abs.starts_with("--") {
            // Boolean flags
            match abs {
                "--greedy-delimiter" => { args.greedy = true; has_any = true; i += 1; continue; }
                "--compress-delimiter" => { args.compress = true; has_any = true; i += 1; continue; }
                "--only-delimited" => { args.only_delimited = true; has_any = true; i += 1; continue; }
                "--zero-terminated" => { args.zero_terminated = true; has_any = true; i += 1; continue; }
                "--complement" => { args.complement = true; has_any = true; i += 1; continue; }
                "--join" => {
                    if args.join == Some(false) {
                        return Err(ParseErr::Runtime(
                            "It's not possible to use --join and --no-join simultaneously".to_string(),
                        ));
                    }
                    args.join = Some(true); has_any = true; i += 1; continue;
                }
                "--no-join" => {
                    if args.join == Some(true) {
                        return Err(ParseErr::Runtime(
                            "It's not possible to use --join and --no-join simultaneously".to_string(),
                        ));
                    }
                    args.join = Some(false); has_any = true; i += 1; continue;
                }
                "--json" => { args.json = true; has_any = true; i += 1; continue; }
                "--no-mmap" => { args.no_mmap = true; has_any = true; i += 1; continue; }
                _ => {}
            }

            // Long options with value
            let (name, value_inline): (&str, Option<&str>) =
                if let Some(eq) = abs.find('=') {
                    (&abs[..eq], Some(&abs[eq+1..]))
                } else {
                    (abs, None)
                };

            let mut take_val = |flag_name: &str| -> Result<String, ParseErr> {
                if let Some(v) = value_inline {
                    return Ok(v.to_string());
                }
                if i + 1 >= raw.len() {
                    return Err(ParseErr::MissingValue(flag_name.to_string()));
                }
                let v = raw[i+1].clone();
                i += 1;
                Ok(v)
            };

            match name {
                "--fields" => { let v = take_val("--fields")?; args.mode = Mode::Fields; args.bounds = v; args.bounds_was_set = true; has_any = true; i += 1; continue; }
                "--bytes" => { let v = take_val("--bytes")?; args.mode = Mode::Bytes; args.bounds = v; args.bounds_was_set = true; has_any = true; i += 1; continue; }
                "--characters" => { let v = take_val("--characters")?; args.mode = Mode::Characters; args.bounds = v; args.bounds_was_set = true; has_any = true; i += 1; continue; }
                "--lines" => { let v = take_val("--lines")?; args.mode = Mode::Lines; args.bounds = v; args.bounds_was_set = true; has_any = true; i += 1; continue; }
                "--delimiter" => { let v = take_val("--delimiter")?; args.delimiter = v; has_any = true; i += 1; continue; }
                "--regex" => { let v = take_val("--regex")?; args.regex = Some(v); has_any = true; i += 1; continue; }
                "--replace-delimiter" => { let v = take_val("--replace-delimiter")?; args.replace_delimiter = Some(v); has_any = true; i += 1; continue; }
                "--trim" => { let v = take_val("--trim")?; args.trim = Some(parse_trim(&v)?); has_any = true; i += 1; continue; }
                "--fallback-oob" => { let v = take_val("--fallback-oob")?; args.fallback_oob = Some(v); has_any = true; i += 1; continue; }
                "--fixed-memory" => {
                    let v = take_val("--fixed-memory")?;
                    let n: u64 = v.parse().map_err(|e: std::num::ParseIntError| {
                        ParseErr::ParseFail(format!("failed to parse '{}': {}", v, e))
                    })?;
                    args.fixed_memory = Some(n);
                    has_any = true;
                    i += 1; continue;
                }
                _ => {
                    unexpected.push(abs.to_string());
                    i += 1;
                    continue;
                }
            }
        }

        // Short options
        if abs.starts_with('-') && abs.len() > 1 {
            let bytes = abs.as_bytes();

            // Handle short options with values: -d,, -f1, -d=,
            let first = bytes[1] as char;
            match first {
                'f' | 'b' | 'c' | 'l' | 'd' | 'e' | 'r' | 't' | 'M' => {
                    // These take a value
                    let value = if bytes.len() > 2 {
                        if bytes[2] == b'=' {
                            abs[3..].to_string()
                        } else {
                            abs[2..].to_string()
                        }
                    } else {
                        if i + 1 >= raw.len() {
                            return Err(ParseErr::MissingValue(format!("-{}", first)));
                        }
                        let v = raw[i+1].clone();
                        i += 1;
                        v
                    };
                    match first {
                        'f' => { args.mode = Mode::Fields; args.bounds = value; args.bounds_was_set = true; }
                        'b' => { args.mode = Mode::Bytes; args.bounds = value; args.bounds_was_set = true; }
                        'c' => { args.mode = Mode::Characters; args.bounds = value; args.bounds_was_set = true; }
                        'l' => { args.mode = Mode::Lines; args.bounds = value; args.bounds_was_set = true; }
                        'd' => { args.delimiter = value; }
                        'e' => { args.regex = Some(value); }
                        'r' => { args.replace_delimiter = Some(value); }
                        't' => { args.trim = Some(parse_trim(&value)?); }
                        'M' => {
                            let n: u64 = value.parse().map_err(|e: std::num::ParseIntError| {
                                ParseErr::ParseFail(format!("failed to parse '{}': {}", value, e))
                            })?;
                            args.fixed_memory = Some(n);
                        }
                        _ => unreachable!(),
                    }
                    has_any = true;
                    i += 1;
                    continue;
                }
                _ => {}
            }

            // Cluster of boolean shorts e.g. -gpsz, -sj
            // Allowed: g, p, s, z, m, j
            let mut all_bool = true;
            for b in &bytes[1..] {
                let c = *b as char;
                if !matches!(c, 'g'|'p'|'s'|'z'|'m'|'j'|'V'|'h') {
                    all_bool = false;
                    break;
                }
            }
            if all_bool && bytes.len() > 1 {
                for b in &bytes[1..] {
                    let c = *b as char;
                    match c {
                        'g' => args.greedy = true,
                        'p' => args.compress = true,
                        's' => args.only_delimited = true,
                        'z' => args.zero_terminated = true,
                        'm' => args.complement = true,
                        'j' => {
                            if args.join == Some(false) {
                                return Err(ParseErr::Runtime(
                                    "It's not possible to use --join and --no-join simultaneously".to_string(),
                                ));
                            }
                            args.join = Some(true);
                        }
                        'V' => { return Err(ParseErr::PrintVersion); }
                        'h' => { return Err(ParseErr::PrintHelp); }
                        _ => {}
                    }
                }
                has_any = true;
                i += 1;
                continue;
            }

            // Unknown short
            unexpected.push(abs.to_string());
            i += 1;
            continue;
        }

        // Positional argument (filepath)
        positional.push(a.clone());
        i += 1;
    }

    if !unexpected.is_empty() {
        // Format as Rust debug list
        let formatted: Vec<String> = unexpected.iter().map(|s| format!("{:?}", s)).collect();
        return Err(ParseErr::Unexpected(format!("[{}]", formatted.join(", "))));
    }

    if positional.len() > 1 {
        let formatted: Vec<String> = positional.iter().map(|s| format!("{:?}", s)).collect();
        return Err(ParseErr::Unexpected(format!("[{}]", formatted.join(", "))));
    }
    if positional.len() == 1 {
        args.filepath = Some(positional.pop().unwrap());
        has_any = true;
    }

    // Handle delimiter escape sequences? The default is "\t" literally typed as \t
    // Treat delimiter as-is; user types actual tab when needed.
    // However, if user didn't set -d but set a mode, default is tab.
    // Already done.

    if !has_any {
        return Err(ParseErr::PrintHelpIntro);
    }

    // Apply post-parse rules
    // -r implies --join
    if args.replace_delimiter.is_some() {
        if args.join == Some(false) {
            return Err(ParseErr::Runtime(
                "You can't pass --no-join when using --replace, which implies --join".to_string(),
            ));
        }
        args.join = Some(true);
    }
    // -l implies --join (unless --no-join)
    if matches!(args.mode, Mode::Lines) {
        if args.join.is_none() {
            args.join = Some(true);
        }
    }

    // JSON support only for Fields and Characters
    if args.json && !matches!(args.mode, Mode::Fields | Mode::Characters) {
        return Err(ParseErr::Runtime(
            "--json support is available only for --fields and --characters".to_string(),
        ));
    }

    // fixed-memory restrictions
    if let Some(n) = args.fixed_memory {
        if n == 0 {
            return Err(ParseErr::Runtime(
                "--fixed-memory cannot be 0".to_string(),
            ));
        }
    }

    Ok(args)
}

fn parse_trim(s: &str) -> Result<Trim, ParseErr> {
    match s {
        "l" | "L" | "left" | "Left" => Ok(Trim::Left),
        "r" | "R" | "right" | "Right" => Ok(Trim::Right),
        "b" | "B" | "both" | "Both" => Ok(Trim::Both),
        _ => Err(ParseErr::ParseFail(format!("failed to parse trim value '{}'", s))),
    }
}
