// Parse bounds like "1,2:3,-1,5=fallback" and format strings "{1}_{2}"

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Side {
    Some(i32),
    Continue, // ":", meaning "to end" on right or "from start" on left
}

#[derive(Debug, Clone)]
pub struct UserBounds {
    pub l: Side,
    pub r: Side,
    pub fallback: Option<String>,
}

#[derive(Debug, Clone)]
pub enum Part {
    Literal(String),
    Field(UserBounds),
}

#[derive(Debug, Clone)]
pub enum BoundsList {
    Simple(Vec<UserBounds>),
    Format(Vec<Part>),
}

fn parse_single_bound(s: &str) -> Result<UserBounds, String> {
    // may contain "=fallback" at the end
    // format: LEFT(:RIGHT)?(=FALLBACK)?
    // split by first '=' that isn't after number? Actually behavior:
    // `1==X` means left="1", fallback="=X" — so split at the FIRST `=`.
    // Wait, tests show `5==X` -> "=X" as fallback (because OOB).
    // So split at first `=`.

    let (main, fallback) = match s.find('=') {
        Some(idx) => (&s[..idx], Some(s[idx+1..].to_string())),
        None => (s, None),
    };

    if main.is_empty() {
        if fallback.is_some() {
            // '=X' case - treat as "1:1"? From observation, "=X" acts like field 1
            // Let me make it equivalent to `1` with this fallback
            return Ok(UserBounds { l: Side::Some(1), r: Side::Some(1), fallback });
        }
        return Err(format!("Field format error: empty field"));
    }

    // Check for ':' to split range
    let (left_s, right_s) = if let Some(idx) = main.find(':') {
        let left = &main[..idx];
        let right = &main[idx+1..];
        if right.contains(':') {
            return Err(format!("Not a number `{}`", right));
        }
        (left, Some(right))
    } else {
        (main, None)
    };

    let parse_side = |part: &str, is_left: bool| -> Result<Side, String> {
        if part.is_empty() {
            // e.g. ":3" or "1:"
            return Ok(Side::Continue);
        }
        let n: i32 = part.parse().map_err(|_| format!("Not a number `{}`", part))?;
        if n == 0 {
            return Err("Zero is not a valid field".to_string());
        }
        let _ = is_left;
        Ok(Side::Some(n))
    };

    match right_s {
        None => {
            // single field
            if left_s.is_empty() {
                return Err("Field format error: empty field".to_string());
            }
            let l = parse_side(left_s, true)?;
            // single field: l==r
            Ok(UserBounds { l: l.clone(), r: l, fallback })
        }
        Some(right) => {
            // range
            if left_s.is_empty() && right.is_empty() {
                return Err("Field format error, no numbers next to `:`".to_string());
            }
            let l = parse_side(left_s, true)?;
            let r = parse_side(right, false)?;
            // Check: left cannot be greater than right when both are concrete
            if let (Side::Some(la), Side::Some(ra)) = (&l, &r) {
                // same sign comparison only (negative ranges are reversed from positive)
                if (*la >= 0 && *ra >= 0 && la > ra) || (*la < 0 && *ra < 0 && la > ra) {
                    return Err("Field left value cannot be greater than right value".to_string());
                }
            }
            Ok(UserBounds { l, r, fallback })
        }
    }
}

pub fn parse_bounds_list(s: &str) -> Result<BoundsList, String> {
    if s.is_empty() {
        return Err("UserBoundsList must contain at least one UserBounds".to_string());
    }
    // Check if it's a format string (contains `{` not as `{{`)
    if has_format_placeholder(s) {
        return parse_format(s).map(BoundsList::Format);
    }
    // Otherwise, parse as simple list
    let parts = split_top_level_commas(s);
    let mut result = Vec::new();
    for p in parts {
        result.push(parse_single_bound(&p).map_err(|e| e)?);
    }
    if result.is_empty() {
        return Err("UserBoundsList must contain at least one UserBounds".to_string());
    }
    Ok(BoundsList::Simple(result))
}

fn split_top_level_commas(s: &str) -> Vec<String> {
    // commas separate entries; but commas don't appear inside fields (no escape).
    s.split(',').map(|x| x.to_string()).collect()
}

fn has_format_placeholder(s: &str) -> bool {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'{' {
            if i + 1 < bytes.len() && bytes[i+1] == b'{' {
                i += 2;
                continue;
            }
            return true;
        }
        i += 1;
    }
    false
}

fn parse_format(s: &str) -> Result<Vec<Part>, String> {
    let bytes = s.as_bytes();
    let mut i = 0;
    let mut parts: Vec<Part> = Vec::new();
    let mut cur = String::new();
    while i < bytes.len() {
        let c = bytes[i];
        if c == b'{' {
            if i + 1 < bytes.len() && bytes[i+1] == b'{' {
                cur.push('{');
                i += 2;
                continue;
            }
            // find matching '}'
            if !cur.is_empty() {
                parts.push(Part::Literal(std::mem::take(&mut cur)));
            }
            // locate '}'
            let mut j = i + 1;
            while j < bytes.len() && bytes[j] != b'}' {
                j += 1;
            }
            if j >= bytes.len() {
                return Err("Field format error: missing closing parenthesis".to_string());
            }
            let inner = &s[i+1..j];
            if inner.is_empty() {
                return Err("Field format error: empty field".to_string());
            }
            let bound = parse_single_bound(inner)?;
            parts.push(Part::Field(bound));
            i = j + 1;
            continue;
        }
        if c == b'}' {
            if i + 1 < bytes.len() && bytes[i+1] == b'}' {
                cur.push('}');
                i += 2;
                continue;
            }
            // stray '}' - also an error
            return Err("Field format error: unexpected '}'".to_string());
        }
        // normal char - we need to handle utf-8 correctly
        // find next boundary
        let start = i;
        while i < bytes.len() && bytes[i] != b'{' && bytes[i] != b'}' {
            i += 1;
        }
        cur.push_str(&s[start..i]);
    }
    if !cur.is_empty() {
        parts.push(Part::Literal(cur));
    }
    if parts.is_empty() {
        return Err("UserBoundsList must contain at least one UserBounds".to_string());
    }
    // Must have at least one field reference
    let has_field = parts.iter().any(|p| matches!(p, Part::Field(_)));
    if !has_field {
        return Err("UserBoundsList must contain at least one UserBounds".to_string());
    }
    Ok(parts)
}

// Resolve bound indices given total number of fields.
// Returns None if out of bounds, or Some((l, r)) 1-indexed inclusive (converted to 0-indexed inside caller).
pub fn resolve_bound(b: &UserBounds, total: i32) -> Option<(i32, i32)> {
    let l = match &b.l {
        Side::Some(n) => {
            if *n > 0 {
                if *n > total { return None; }
                *n
            } else {
                let v = total + n + 1;
                if v < 1 { return None; }
                v
            }
        }
        Side::Continue => 1,
    };
    let r = match &b.r {
        Side::Some(n) => {
            if *n > 0 {
                if *n > total { return None; }
                *n
            } else {
                let v = total + n + 1;
                if v < 1 { return None; }
                v
            }
        }
        Side::Continue => total,
    };
    if l > r {
        return None;
    }
    Some((l, r))
}

// Given a UserBounds and total, resolve considering fallback.
// Returns Ok with resolved (l, r) or Err with fallback (or None for global fallback).
pub fn resolve_or_fallback(
    b: &UserBounds,
    total: i32,
) -> Result<(i32, i32), Option<String>> {
    match resolve_bound(b, total) {
        Some(x) => Ok(x),
        None => Err(b.fallback.clone()),
    }
}

// Complement a single bound — return a list of bounds that are the complement.
// Complement is per-bound, not per-list.
pub fn complement_bound(b: &UserBounds) -> Vec<UserBounds> {
    // Find L and R as i32 OR special
    // We produce 1 or 2 bounds:
    // If l==1 and r==end: complement is nothing (empty)
    // If l==1: one bound (r+1, end)
    // If r==end: one bound (1, l-1)
    // Else: two bounds (1, l-1) and (r+1, end)

    let (l_val, l_kind) = match &b.l {
        Side::Some(n) => (Some(*n), "num"),
        Side::Continue => (None, "start"),
    };
    let (r_val, r_kind) = match &b.r {
        Side::Some(n) => (Some(*n), "num"),
        Side::Continue => (None, "end"),
    };
    let _ = (l_kind, r_kind);

    // For simplicity, only handle positive numbered cases cleanly for complement
    // If either is negative, we'd need to know total...
    // The tool stores bounds and resolves later. Let's store "complemented" bounds.

    // We'll create bounds using special Side values.
    // For: [l, r] complement = [start, l-1] + [r+1, end]
    let mut result = Vec::new();

    // Compute l-1 as Side
    let minus_one_from = |s: &Side| -> Option<Side> {
        match s {
            Side::Some(n) => {
                if *n == 1 { None } // empty range below
                else if *n == 0 { unreachable!() }
                else if *n > 0 { Some(Side::Some(n - 1)) }
                else { Some(Side::Some(n - 1)) } // e.g. -1 becomes -2 (one earlier)
            }
            Side::Continue => None, // l=start means nothing before
        }
    };

    let plus_one_from = |s: &Side| -> Option<Side> {
        match s {
            Side::Some(n) => {
                if *n == -1 { None } // nothing after
                else if *n == 0 { unreachable!() }
                else if *n > 0 { Some(Side::Some(n + 1)) }
                else { Some(Side::Some(n + 1)) }
            }
            Side::Continue => None, // r=end means nothing after
        }
    };

    // Left part: from start to l-1
    let left_upper = minus_one_from(&b.l);
    if let Some(lu) = left_upper {
        result.push(UserBounds {
            l: Side::Continue,
            r: lu,
            fallback: None,
        });
    }
    // Right part: from r+1 to end
    let right_lower = plus_one_from(&b.r);
    if let Some(rl) = right_lower {
        result.push(UserBounds {
            l: rl,
            r: Side::Continue,
            fallback: None,
        });
    }

    // Note: If the bound was l/r with mixed signs, the complement might not be well-defined,
    // but for simplicity we just handle basic cases.

    result
}

// For checking if bounds are "forward" (ascending, non-negative)
pub fn is_simple_forward(bounds: &[UserBounds]) -> bool {
    let mut prev_end: i32 = 0;
    for b in bounds {
        let l = match &b.l {
            Side::Some(n) if *n > 0 => *n,
            Side::Continue => 1,
            _ => return false,
        };
        let r = match &b.r {
            Side::Some(n) if *n > 0 => *n,
            Side::Continue => i32::MAX,
            _ => return false,
        };
        if l < prev_end {
            return false;
        }
        prev_end = r;
    }
    true
}
