                    }
                }
            }
            // Trailing terminator
            out.write_all(&[term]).map_err(io_to_run_err)?;
        }
        BoundsList::Format(parts) => {
            // Each part treated — emit with terminator separator
            let mut first = true;
            for p in parts {
                match p {
                    Part::Literal(t) => {
                        if !first { out.write_all(&[term]).map_err(io_to_run_err)?; }
                        first = false;
                        out.write_all(t.as_bytes()).map_err(io_to_run_err)?;
                    }
