// Cut logic for different modes

use std::io::Write;
use crate::args::{Args, Mode, Trim};
use crate::bounds::{BoundsList, Part, UserBounds, Side, parse_bounds_list, resolve_or_fallback, complement_bound};

pub enum RunErr {
    Runtime(String),
    SilentFail,
}

pub fn run<W: Write, E: Write>(args: &Args, input: &[u8], out: &mut W, err: &mut E) -> Result<(), RunErr> {
    // Regex is not supported in this implementation
    if args.regex.is_some() {
        return Err(RunErr::Runtime(
            "The regex feature is not supported in this build".to_string(),
        ));
    }

    // Parse bounds
    let bounds_list = match parse_bounds_list(&args.bounds) {
        Ok(b) => b,
        Err(e) => {
            return Err(RunErr::Runtime(format!("__PARSE_FAIL__: failed to parse '{}': {}", args.bounds, e)));
        }
    };

    // Validate JSON constraints
    if args.json {
        if args.replace_delimiter.is_some() {
            return Err(RunErr::Runtime(
                "The use of --replace with --json is not supported".to_string(),
            ));
        }
        if let BoundsList::Format(parts) = &bounds_list {
            for p in parts {
                if let Part::Literal(_) = p {
                    return Err(RunErr::Runtime(
                        "Cannot format fields when using --json".to_string(),
                    ));
                }
            }
        }
    }

    // Apply complement if needed
    let bounds_list = if args.complement {
        match bounds_list {
            BoundsList::Simple(entries) => {
                let mut new_entries: Vec<UserBounds> = Vec::new();
                for b in &entries {
                    new_entries.extend(complement_bound(b));
                }
                if new_entries.is_empty() {
                    return Err(RunErr::Runtime(
                        "UserBoundsList must contain at least one UserBounds".to_string(),
                    ));
                }
                BoundsList::Simple(new_entries)
            }
            BoundsList::Format(_) => bounds_list,
        }
    } else {
        bounds_list
    };

    match args.mode {
        Mode::Bytes => run_bytes(args, input, &bounds_list, out, err),
        Mode::Characters => run_characters(args, input, &bounds_list, out, err),
        Mode::Fields => run_fields(args, input, &bounds_list, out, err),
        Mode::Lines => run_lines(args, input, &bounds_list, out, err),
    }
}

fn line_term(args: &Args) -> u8 {
    if args.zero_terminated { b'\0' } else { b'\n' }
}

fn split_lines<'a>(input: &'a [u8], term: u8) -> Vec<(&'a [u8], bool)> {
    let mut lines = Vec::new();
    let mut start = 0;
    for i in 0..input.len() {
        if input[i] == term {
            lines.push((&input[start..i], true));
            start = i + 1;
        }
    }
    if start < input.len() {
        lines.push((&input[start..], false));
    }
    lines
}

fn apply_compress_str(s: &str, delim: &str) -> String {
    if delim.is_empty() { return s.to_string(); }
    let mut out = String::new();
    let mut i = 0;
    let bytes = s.as_bytes();
    let dbytes = delim.as_bytes();
    let dlen = dbytes.len();
    while i < bytes.len() {
        if i + dlen <= bytes.len() && &bytes[i..i+dlen] == dbytes {
            out.push_str(delim);
            i += dlen;
            while i + dlen <= bytes.len() && &bytes[i..i+dlen] == dbytes {
                i += dlen;
            }
        } else {
            let ch = s[i..].chars().next().unwrap();
            out.push(ch);
            i += ch.len_utf8();
        }
    }
    out
}

fn apply_trim_str(s: &str, delim: &str, trim: Trim) -> String {
    if delim.is_empty() { return s.to_string(); }
    let bytes = s.as_bytes();
    let dbytes = delim.as_bytes();
    let dlen = dbytes.len();
    let mut start = 0;
    let mut end = bytes.len();
    if matches!(trim, Trim::Left | Trim::Both) {
        while start + dlen <= end && &bytes[start..start+dlen] == dbytes {
            start += dlen;
        }
    }
    if matches!(trim, Trim::Right | Trim::Both) {
        while end >= start + dlen && &bytes[end - dlen..end] == dbytes {
            end -= dlen;
        }
    }
    std::str::from_utf8(&bytes[start..end]).unwrap_or("").to_string()
}

// Split line into fields with their byte positions.
// Returns a list of (start, end, is_field) segments. Alternating field/delim/field.
// For convenience, also returns the fields positions only.
// If greedy: consecutive delimiters are merged into one "delim segment" but fields still split
// by each delimiter boundary? Actually greedy treats multiple delims as one separator between fields.
// So "a,,,b" with -g has fields "a", "b".
fn split_fields_with_pos<'a>(line: &'a str, delim: &str, greedy: bool) -> (Vec<(usize, usize)>, Vec<(usize, usize)>) {
    // Returns (fields, delim_segments) where each is (start, end) byte offset in line.
    let bytes = line.as_bytes();
    let dbytes = delim.as_bytes();
    let dlen = dbytes.len();
    let mut fields = Vec::new();
    let mut delims = Vec::new();
    if dlen == 0 {
        fields.push((0, bytes.len()));
        return (fields, delims);
    }

    let mut start = 0;
    let mut i = 0;
    while i + dlen <= bytes.len() {
        if &bytes[i..i+dlen] == dbytes {
            fields.push((start, i));
            let ds = i;
            i += dlen;
            if greedy {
                while i + dlen <= bytes.len() && &bytes[i..i+dlen] == dbytes {
                    i += dlen;
                }
            }
            delims.push((ds, i));
            start = i;
        } else {
            i += 1;
        }
    }
    fields.push((start, bytes.len()));
    (fields, delims)
}

fn emit_json_string<W: Write>(out: &mut W, s: &str) -> std::io::Result<()> {
    out.write_all(b"\"")?;
    for c in s.chars() {
        match c {
            '"' => out.write_all(b"\\\"")?,
            '\\' => out.write_all(b"\\\\")?,
            '\n' => out.write_all(b"\\n")?,
            '\r' => out.write_all(b"\\r")?,
            '\t' => out.write_all(b"\\t")?,
            '\x08' => out.write_all(b"\\b")?,
            '\x0C' => out.write_all(b"\\f")?,
            c if (c as u32) < 0x20 => {
                write!(out, "\\u{:04x}", c as u32)?;
            }
            c => {
                let mut buf = [0u8; 4];
                out.write_all(c.encode_utf8(&mut buf).as_bytes())?;
            }
        }
    }
    out.write_all(b"\"")?;
    Ok(())
}

fn write_oob_err<E: Write>(err: &mut E, b: &UserBounds) -> std::io::Result<()> {
    let mut s = String::new();
    match &b.l {
        Side::Some(n) => s.push_str(&n.to_string()),
        Side::Continue => {}
    }
    let is_range = match (&b.l, &b.r) {
        (Side::Some(a), Side::Some(b2)) => a != b2,
        (Side::Continue, _) | (_, Side::Continue) => true,
    };
    if is_range {
        s.push(':');
        match &b.r {
            Side::Some(n) => s.push_str(&n.to_string()),
            Side::Continue => {}
        }
    }
    writeln!(err, "Error: Out of bounds: {}", s)
}

fn io_to_run_err(e: std::io::Error) -> RunErr {
    RunErr::Runtime(e.to_string())
}

// Replace all occurrences of `delim` in `segment` with `new_delim`.
fn replace_delims(segment: &str, delim: &str, new_delim: &str) -> String {
    if delim.is_empty() { return segment.to_string(); }
    // Replace multi-byte delim
    let mut out = String::new();
    let bytes = segment.as_bytes();
    let dbytes = delim.as_bytes();
    let dlen = dbytes.len();
    let mut i = 0;
    while i < bytes.len() {
        if i + dlen <= bytes.len() && &bytes[i..i+dlen] == dbytes {
            out.push_str(new_delim);
            i += dlen;
        } else {
            let ch = segment[i..].chars().next().unwrap();
            out.push(ch);
            i += ch.len_utf8();
        }
    }
    out
}

// Write the substring from field L to field R (preserving delimiters in between).
// If replace-delimiter is set, replace delims with it.
fn write_range<W: Write>(
    out: &mut W,
    line: &str,
    fields: &[(usize, usize)],
    l: i32, r: i32,
    args: &Args,
) -> std::io::Result<()> {
    let l = (l - 1) as usize;
    let r = (r - 1) as usize;
    let start = fields[l].0;
    let end = fields[r].1;
    let sub = &line[start..end];
    if let Some(new_d) = &args.replace_delimiter {
        let replaced = replace_delims(sub, &args.delimiter, new_d);
        out.write_all(replaced.as_bytes())?;
    } else {
        out.write_all(sub.as_bytes())?;
    }
    Ok(())
}

fn run_fields<W: Write, E: Write>(
    args: &Args, input: &[u8], bounds_list: &BoundsList, out: &mut W, err: &mut E,
) -> Result<(), RunErr> {
    let term = line_term(args);
    let lines = split_lines(input, term);
    let delim = &args.delimiter;
    let mut any_err = false;

    for (line_bytes, had_term) in &lines {
        let line_owned_vec = line_bytes.to_vec();
        let line_orig = match std::str::from_utf8(&line_owned_vec) {
            Ok(s) => s.to_string(),
            Err(_) => return Err(RunErr::Runtime("input is not valid UTF-8".to_string())),
        };

        if line_orig.is_empty() {
            if *had_term { out.write_all(&[term]).map_err(io_to_run_err)?; }
            continue;
        }

        let processed = if let Some(t) = args.trim {
            apply_trim_str(&line_orig, delim, t)
        } else {
            line_orig.clone()
        };
        let processed = if args.compress {
            apply_compress_str(&processed, delim)
        } else {
            processed
        };

        let (fields, _delims) = split_fields_with_pos(&processed, delim, args.greedy);

        if args.only_delimited && fields.len() <= 1 {
            continue;
        }

        let total = fields.len() as i32;
        let join_delim: &str = match &args.replace_delimiter {
            Some(s) => s.as_str(),
            None => delim,
        };
        let do_join = args.join.unwrap_or(false);

        if args.json {
            let mut collected: Vec<String> = Vec::new();
            match bounds_list {
                BoundsList::Simple(entries) => {
                    for b in entries {
                        match resolve_or_fallback(b, total) {
                            Ok((l, r)) => {
                                for idx in l..=r {
                                    let (s, e) = fields[(idx - 1) as usize];
                                    collected.push(processed[s..e].to_string());
                                }
                            }
                            Err(fb) => {
                                let fallback = fb.or_else(|| args.fallback_oob.clone());
                                if let Some(f) = fallback {
                                    collected.push(f);
                                } else {
                                    any_err = true;
                                    let _ = write_oob_err(err, b);
                                }
                            }
                        }
                    }
                }
                BoundsList::Format(parts) => {
                    for p in parts {
                        if let Part::Field(b) = p {
                            match resolve_or_fallback(b, total) {
                                Ok((l, r)) => {
                                    for idx in l..=r {
                                        let (s, e) = fields[(idx - 1) as usize];
                                        collected.push(processed[s..e].to_string());
                                    }
                                }
                                Err(fb) => {
                                    let fallback = fb.or_else(|| args.fallback_oob.clone());
                                    if let Some(f) = fallback {
                                        collected.push(f);
                                    } else {
                                        any_err = true;
                                        let _ = write_oob_err(err, b);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            out.write_all(b"[").map_err(io_to_run_err)?;
            for (i, s) in collected.iter().enumerate() {
                if i > 0 { out.write_all(b",").map_err(io_to_run_err)?; }
                emit_json_string(out, s).map_err(io_to_run_err)?;
            }
            out.write_all(b"]").map_err(io_to_run_err)?;
            if *had_term {
                out.write_all(&[term]).map_err(io_to_run_err)?;
            } else {
                out.write_all(&[term]).map_err(io_to_run_err)?;
            }
            continue;
        }

        match bounds_list {
            BoundsList::Simple(entries) => {
                let mut first = true;
                for b in entries {
                    match resolve_or_fallback(b, total) {
                        Ok((l, r)) => {
                            if !first && do_join {
                                out.write_all(join_delim.as_bytes()).map_err(io_to_run_err)?;
                            }
                            first = false;
                            write_range(out, &processed, &fields, l, r, args).map_err(io_to_run_err)?;
                        }
                        Err(fb) => {
                            let fallback = fb.or_else(|| args.fallback_oob.clone());
                            if let Some(f) = fallback {
                                if !first && do_join {
                                    out.write_all(join_delim.as_bytes()).map_err(io_to_run_err)?;
                                }
                                first = false;
                                out.write_all(f.as_bytes()).map_err(io_to_run_err)?;
                            } else {
                                any_err = true;
                                let _ = write_oob_err(err, b);
                            }
                        }
                    }
                }
            }
            BoundsList::Format(parts) => {
                for p in parts {
                    match p {
                        Part::Literal(t) => { out.write_all(t.as_bytes()).map_err(io_to_run_err)?; }
                        Part::Field(b) => {
                            match resolve_or_fallback(b, total) {
                                Ok((l, r)) => {
                                    write_range(out, &processed, &fields, l, r, args).map_err(io_to_run_err)?;
                                }
                                Err(fb) => {
                                    let fallback = fb.or_else(|| args.fallback_oob.clone());
                                    if let Some(f) = fallback {
                                        out.write_all(f.as_bytes()).map_err(io_to_run_err)?;
                                    } else {
                                        any_err = true;
                                        let _ = write_oob_err(err, b);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        if *had_term {
            out.write_all(&[term]).map_err(io_to_run_err)?;
        }
    }

    if any_err {
        return Err(RunErr::SilentFail);
    }
    Ok(())
}

fn run_characters<W: Write, E: Write>(
    args: &Args, input: &[u8], bounds_list: &BoundsList, out: &mut W, err: &mut E,
) -> Result<(), RunErr> {
    let term = line_term(args);
    let lines = split_lines(input, term);
    let mut any_err = false;

    for (line_bytes, had_term) in &lines {
        let line = match std::str::from_utf8(line_bytes) {
            Ok(s) => s,
            Err(_) => return Err(RunErr::Runtime("input is not valid UTF-8".to_string())),
        };
        if line.is_empty() {
            if *had_term { out.write_all(&[term]).map_err(io_to_run_err)?; }
            continue;
        }

        // Build per-char positions
        let mut positions: Vec<(usize, usize)> = Vec::new();
        for (i, c) in line.char_indices() {
            positions.push((i, i + c.len_utf8()));
        }
        let total = positions.len() as i32;

        let do_join = args.join.unwrap_or(false);
        let join_delim: &str = match &args.replace_delimiter {
            Some(s) => s.as_str(),
            None => "",
        };

        if args.json {
            let mut collected: Vec<String> = Vec::new();
            match bounds_list {
                BoundsList::Simple(entries) => {
                    for b in entries {
                        match resolve_or_fallback(b, total) {
                            Ok((l, r)) => {
                                for idx in l..=r {
                                    let (s, e) = positions[(idx - 1) as usize];
                                    collected.push(line[s..e].to_string());
                                }
                            }
                            Err(fb) => {
                                let fallback = fb.or_else(|| args.fallback_oob.clone());
                                if let Some(f) = fallback {
                                    collected.push(f);
                                } else {
                                    any_err = true;
                                    let _ = write_oob_err(err, b);
                                }
                            }
                        }
                    }
                }
                BoundsList::Format(parts) => {
                    for p in parts {
                        if let Part::Field(b) = p {
                            match resolve_or_fallback(b, total) {
                                Ok((l, r)) => {
                                    for idx in l..=r {
                                        let (s, e) = positions[(idx - 1) as usize];
                                        collected.push(line[s..e].to_string());
                                    }
                                }
                                Err(fb) => {
                                    let fallback = fb.or_else(|| args.fallback_oob.clone());
                                    if let Some(f) = fallback { collected.push(f); }
                                    else { any_err = true; let _ = write_oob_err(err, b); }
                                }
                            }
                        }
                    }
                }
            }
            out.write_all(b"[").map_err(io_to_run_err)?;
            for (i, s) in collected.iter().enumerate() {
                if i > 0 { out.write_all(b",").map_err(io_to_run_err)?; }
                emit_json_string(out, s).map_err(io_to_run_err)?;
            }
            out.write_all(b"]").map_err(io_to_run_err)?;
            out.write_all(&[term]).map_err(io_to_run_err)?;
            continue;
        }

        match bounds_list {
            BoundsList::Simple(entries) => {
                let mut first = true;
                for b in entries {
                    match resolve_or_fallback(b, total) {
                        Ok((l, r)) => {
                            if !first && do_join {
                                out.write_all(join_delim.as_bytes()).map_err(io_to_run_err)?;
                            }
                            first = false;
                            let s = positions[(l - 1) as usize].0;
                            let e = positions[(r - 1) as usize].1;
                            out.write_all(line[s..e].as_bytes()).map_err(io_to_run_err)?;
                        }
                        Err(fb) => {
                            let fallback = fb.or_else(|| args.fallback_oob.clone());
                            if let Some(f) = fallback {
                                if !first && do_join {
                                    out.write_all(join_delim.as_bytes()).map_err(io_to_run_err)?;
                                }
                                first = false;
                                out.write_all(f.as_bytes()).map_err(io_to_run_err)?;
                            } else {
                                any_err = true;
                                let _ = write_oob_err(err, b);
                            }
                        }
                    }
                }
            }
            BoundsList::Format(parts) => {
                for p in parts {
                    match p {
                        Part::Literal(t) => { out.write_all(t.as_bytes()).map_err(io_to_run_err)?; }
                        Part::Field(b) => {
                            match resolve_or_fallback(b, total) {
                                Ok((l, r)) => {
                                    let s = positions[(l - 1) as usize].0;
                                    let e = positions[(r - 1) as usize].1;
                                    out.write_all(line[s..e].as_bytes()).map_err(io_to_run_err)?;
                                }
                                Err(fb) => {
                                    let fallback = fb.or_else(|| args.fallback_oob.clone());
                                    if let Some(f) = fallback {
                                        out.write_all(f.as_bytes()).map_err(io_to_run_err)?;
                                    } else {
                                        any_err = true;
                                        let _ = write_oob_err(err, b);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        if *had_term { out.write_all(&[term]).map_err(io_to_run_err)?; }
    }

    if any_err { return Err(RunErr::SilentFail); }
    Ok(())
}

fn run_bytes<W: Write, E: Write>(
    args: &Args, input: &[u8], bounds_list: &BoundsList, out: &mut W, err: &mut E,
) -> Result<(), RunErr> {
    let total = input.len() as i32;
    let do_join = args.join.unwrap_or(false);
    let join_delim: &str = match &args.replace_delimiter {
        Some(s) => s.as_str(),
        None => "",
    };

    match bounds_list {
        BoundsList::Simple(entries) => {
            let mut first = true;
            for b in entries {
                match resolve_or_fallback(b, total) {
                    Ok((l, r)) => {
                        if !first && do_join {
                            out.write_all(join_delim.as_bytes()).map_err(io_to_run_err)?;
                        }
                        first = false;
                        out.write_all(&input[(l-1) as usize..r as usize]).map_err(io_to_run_err)?;
                    }
                    Err(fb) => {
                        let fallback = fb.or_else(|| args.fallback_oob.clone());
                        if let Some(f) = fallback {
                            if !first && do_join {
                                out.write_all(join_delim.as_bytes()).map_err(io_to_run_err)?;
                            }
                            first = false;
                            out.write_all(f.as_bytes()).map_err(io_to_run_err)?;
                        } else {
                            let _ = write_oob_err(err, b);
                            return Err(RunErr::SilentFail);
                        }
                    }
                }
            }
        }
        BoundsList::Format(parts) => {
            for p in parts {
                match p {
                    Part::Literal(t) => { out.write_all(t.as_bytes()).map_err(io_to_run_err)?; }
                    Part::Field(b) => {
                        match resolve_or_fallback(b, total) {
                            Ok((l, r)) => {
                                out.write_all(&input[(l-1) as usize..r as usize]).map_err(io_to_run_err)?;
                            }
                            Err(fb) => {
                                let fallback = fb.or_else(|| args.fallback_oob.clone());
                                if let Some(f) = fallback {
                                    out.write_all(f.as_bytes()).map_err(io_to_run_err)?;
                                } else {
                                    let _ = write_oob_err(err, b);
                                    return Err(RunErr::SilentFail);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

// Streaming -l implementation
fn run_lines<W: Write, E: Write>(
    args: &Args, input: &[u8], bounds_list: &BoundsList, out: &mut W, err: &mut E,
) -> Result<(), RunErr> {
    let term = line_term(args);
    let lines = split_lines(input, term);
    let line_strs: Vec<&str> = lines.iter().map(|(b, _)| std::str::from_utf8(b).unwrap_or("")).collect();

    let join_delim: String = match &args.replace_delimiter {
        Some(s) => s.clone(),
        None => {
            let mut s = String::new();
            s.push(term as char);
            s
        }
    };
    let do_join = args.join.unwrap_or(true);

    // Streaming approach: iterate lines, track cursor per-bound.
    // For Simple bounds, use streaming semantics.
    match bounds_list {
        BoundsList::Simple(entries) => {
            // Pre-validate: bounds must be ascending (Li >= R_{i-1}) for concrete positive values.
            // For negatives or non-ascending, we follow original quirky behavior.
            // Simpler strategy: iterate lines, and per-line try to match each bound.
            // We'll emulate the "cursor" approach:
            //   - cursor = 1
            //   - for each bound in order:
            //     - let L, R be resolved at current stage.
            //     - L must be >= cursor.
            //     - emit lines L..=R.
            //     - cursor = R + 1.
            //   - if any bound's R > total, or L > total, error.
            //
            // But the total is fixed (we read all lines).
            // For negative indices, we resolve against total.

            let total = line_strs.len() as i32;
            let mut cursor: i32 = 1;
            let mut first = true;
            let mut any_err = false;

            // Check if all bounds have positive (or continue) and are ascending for streaming semantics
            let mut has_negative = false;
            for b in entries {
                if let Side::Some(n) = &b.l { if *n < 0 { has_negative = true; break; } }
                if let Side::Some(n) = &b.r { if *n < 0 { has_negative = true; break; } }
            }
            // If has_negative, for each line, mimic the original
            if has_negative {
                // Iterate line-by-line: for each line, resolve bound with current line count.
                // Emit if current line matches.
                // Actually the original "streaming -l -1" emits every line (treating each line as last).
                // For each bound, we emit if resolved (l, r) contains current_line.
                // Use "streaming total" = current line count.
                let mut current_count: i32 = 0;
                for (idx, (_, had_term)) in lines.iter().enumerate() {
                    current_count += 1;
                    // For each bound, try to resolve with current_count
                    for b in entries {
                        match resolve_or_fallback(b, current_count) {
                            Ok((l, r)) => {
                                if current_count >= l && current_count <= r {
                                    if !first && do_join {
                                        out.write_all(join_delim.as_bytes()).map_err(io_to_run_err)?;
                                    }
                                    first = false;
                                    out.write_all(line_strs[idx].as_bytes()).map_err(io_to_run_err)?;
                                }
                            }
                            Err(_fb) => {
                                let _ = write_oob_err(err, b);
                                any_err = true;
                                // stop emitting further
                                if any_err { break; }
                            }
                        }
                    }
                    if any_err { break; }
                    let _ = had_term;
                }
                if !first {
                    out.write_all(&[term]).map_err(io_to_run_err)?;
                }
                if any_err { return Err(RunErr::SilentFail); }
                return Ok(());
            }

            for b in entries {
                let l = match &b.l {
                    Side::Some(n) => *n,
                    Side::Continue => cursor,
                };
                let r = match &b.r {
                    Side::Some(n) => *n,
                    Side::Continue => total,
                };
                if l < cursor {
                    // Error: report previous bound's R (cursor-1) as the value
                    let prev_end = cursor - 1;
                    writeln!(err, "Error: Out of bounds: {}", prev_end).map_err(io_to_run_err)?;
                    return Err(RunErr::SilentFail);
                }
                if l > total || r > total {
                    // OOB
                    let fallback = b.fallback.clone().or_else(|| args.fallback_oob.clone());
                    if let Some(f) = fallback {
                        if !first && do_join {
                            out.write_all(join_delim.as_bytes()).map_err(io_to_run_err)?;
                        }
                        first = false;
                        out.write_all(f.as_bytes()).map_err(io_to_run_err)?;
                        cursor = r + 1;
                        continue;
                    } else {
                        let _ = write_oob_err(err, b);
                        any_err = true;
                        continue;
                    }
                }
                for idx in l..=r {
                    if !first && do_join {
                        out.write_all(join_delim.as_bytes()).map_err(io_to_run_err)?;
                    }
                    first = false;
                    out.write_all(line_strs[(idx - 1) as usize].as_bytes()).map_err(io_to_run_err)?;
                }
                cursor = r + 1;
            }
            if !first {
                out.write_all(&[term]).map_err(io_to_run_err)?;
            }
            if any_err { return Err(RunErr::SilentFail); }
            Ok(())
        }
        BoundsList::Format(parts) => {
            let total = line_strs.len() as i32;
            let mut first = true;
            let mut any_err = false;
            for p in parts {
                match p {
                    Part::Literal(t) => {
                        if !first { out.write_all(&[term]).map_err(io_to_run_err)?; }
                        first = false;
                        out.write_all(t.as_bytes()).map_err(io_to_run_err)?;
                    }
                    Part::Field(b) => {
                        match resolve_or_fallback(b, total) {
                            Ok((l, r)) => {
                                for idx in l..=r {
                                    if !first { out.write_all(&[term]).map_err(io_to_run_err)?; }
                                    first = false;
                                    out.write_all(line_strs[(idx - 1) as usize].as_bytes()).map_err(io_to_run_err)?;
                                }
                            }
                            Err(fb) => {
                                let fallback = fb.or_else(|| args.fallback_oob.clone());
                                if let Some(f) = fallback {
                                    if !first { out.write_all(&[term]).map_err(io_to_run_err)?; }
                                    first = false;
                                    out.write_all(f.as_bytes()).map_err(io_to_run_err)?;
                                } else {
                                    any_err = true;
                                    let _ = write_oob_err(err, b);
                                }
                            }
                        }
                    }
                }
            }
            if !first { out.write_all(&[term]).map_err(io_to_run_err)?; }
            if any_err { return Err(RunErr::SilentFail); }
            Ok(())
        }
    }
}
